223	     * This is rather advanced GUI stuff - you can ignore this 
224	     * for your project if you like.
225	     */
226	    private class FieldView extends JPanel
227	    {
228	        private final int GRID_VIEW_SCALING_FACTOR = 6;
229	
230	        private int gridWidth, gridHeight;
231	        private int xScale, yScale;
232	        Dimension size;
233	        private Graphics g;
234	        private Image fieldImage;
235	
236	        /**
237	         * Create a new FieldView component.
238	         */
239	        public FieldView(int height, int width)
240	        {
241	            gridHeight = height;
242	            gridWidth = width;
243	            size = new Dimension(0, 0);
244	        }
245	
246	        /**
247	         * Tell the GUI manager how big we would like to be.
248	         */
249	        public Dimension getPreferredSize()
250	        {
251	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
252	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
253	        }
254	
255	        /**
256	         * Prepare for a new round of painting. Since the component
257	         * may be resized, compute the scaling factor again.
258	         */
259	        public void preparePaint()
260	        {
261	            // If the size has changed:
262	            if (!size.equals(getSize()))
263	            {
264	                size = getSize();
265	                fieldImage = fieldView.createImage(size.width, size.height);
266	                g = fieldImage.getGraphics();
267	
268	                xScale = size.width / gridWidth;
269	                
270	                if (xScale < 1) xScale = GRID_VIEW_SCALING_FACTOR;
271	                
272	                yScale = size.height / gridHeight;
273	                
274	                if (yScale < 1) yScale = GRID_VIEW_SCALING_FACTOR;
275	            }
276	        }
277	        
278	        /**
279	         * Paint on grid location on this field in a given color.
280	         */
281	        public void drawMark(int x, int y, Color color)
282	        {
283	            g.setColor(color);
284	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
285	        }
286	
287	        /**
288	         * The field view component needs to be redisplayed. Copy the
289	         * internal image to screen.
290	         */
291	        public void paintComponent(Graphics g)
292	        {
293	            if (fieldImage != null)
294	            {
295	                Dimension currentSize = getSize();
296	                
297	                if (size.equals(currentSize)) g.drawImage(fieldImage, 0, 0, null);
298	                // Else, rescale the previous image:
299	                else g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
300	            }
301	        }
302	    }
303	}
